((root,factory)=>{const api=factory(typeof module==='object'&&module.exports?require('./persamaan-linear-core.js'):root.LinearLesson);if(typeof module==='object'&&module.exports)module.exports=api;else root.MixedPractice=api;})(typeof window==='undefined'?globalThis:window,num=>{
'use strict';
const groups=[{id:'a',title:'Bilangan, aljabar, dan syarat solusi',chapters:'Bab 1–6'},{id:'b',title:'Koordinat dan fungsi',chapters:'Bab 7–11'},{id:'c',title:'Keluarga fungsi dan trigonometri',chapters:'Bab 12–15'},{id:'d',title:'Perubahan, limit, dan garis singgung',chapters:'Bab 16–18'}];
const questions=[
{id:'m01',group:'a',kind:'number',tex:String.raw`\frac{\sqrt{12}+\sqrt{27}}{\sqrt3}`,prompt:'Sederhanakan bentuknya. Berapa nilainya?',n:5,d:1,hint:'Sederhanakan masing-masing akar sebelum menjumlahkan. Penyebut bukan nol.',why:'Akar dua belas adalah dua akar tiga dan akar dua puluh tujuh adalah tiga akar tiga. Jumlahnya lima akar tiga; dibagi akar tiga menghasilkan lima.',worked:String.raw`\frac{2\sqrt3+3\sqrt3}{\sqrt3}=5`,review:[['bentuk-akar.html','Bentuk akar dan pangkat rasional'],['distributif.html','Suku dan sifat distributif']]},
{id:'m02',group:'a',kind:'choice',tex:String.raw`\frac{x^2-9}{x-3}=6`,prompt:'Manakah himpunan solusi yang benar setelah memperhatikan syarat awal?',options:[String.raw`\{3\}`,String.raw`\varnothing`,String.raw`\{-3,3\}`],answer:1,hint:'Faktorkan pembilang. Catat nilai yang membuat penyebut nol sebelum menyederhanakan.',why:'Pada domain selain tiga, pecahan sama dengan masukan ditambah tiga. Kandidat tiga justru dilarang pada bentuk awal. Jadi tidak ada solusi.',worked:String.raw`x\ne3,\quad x+3=6\Rightarrow x=3\ \text{ditolak}`,review:[['faktorisasi.html','Faktorisasi dan syarat penyebut'],['persamaan-pecahan-akar.html','Kandidat dan solusi persamaan pecahan']]},
{id:'m03',group:'a',kind:'choice',tex:String.raw`|2x-1|\le3`,prompt:'Pilih interval seluruh solusi.',options:[String.raw`[-1,2]`,String.raw`(-1,2)`,String.raw`(-\infty,-1]\cup[2,\infty)`],answer:0,hint:'Jarak paling banyak tiga berarti isi mutlak berada di antara negatif tiga dan tiga, termasuk batas.',why:'Tulis negatif tiga kurang dari atau sama dengan dua kali masukan dikurangi satu, dan bentuk itu paling banyak tiga. Tambahkan satu lalu bagi dua pada ketiga bagian.',worked:String.raw`-3\le2x-1\le3\Longleftrightarrow-1\le x\le2`,review:[['nilai-mutlak.html','Persamaan dan pertidaksamaan nilai mutlak'],['pertidaksamaan-majemuk.html','Irisan dan batas interval']]},
{id:'m04',group:'b',kind:'number',tex:String.raw`\begin{gathered}A=(-1,2),\quad B=(3,4)\\M=\text{titik tengah }AB,\quad f(x)=2x+1\end{gathered}`,prompt:'Gunakan koordinat mendatar titik tengah sebagai masukan fungsi. Berapa keluarannya?',n:3,d:1,hint:'Rata-ratakan koordinat mendatar yang sejenis. Jangan memakai panjang ruas sebagai masukan.',why:'Titik tengah mempunyai koordinat satu dan tiga. Masukan yang diminta adalah satu, sehingga dua kali satu ditambah satu menghasilkan tiga.',worked:String.raw`M=(1,3),\quad f(1)=3`,review:[['jarak-titik-tengah.html','Titik tengah'],['fungsi.html','Notasi dan evaluasi fungsi']]},
{id:'m05',group:'b',kind:'choice',tex:String.raw`f(x)=x^2,\quad D_f=[0,\infty),\quad g=f^{-1}`,prompt:'Apa yang terjadi pada ekspresi g(f(−2)) dengan domain yang dinyatakan?',options:[String.raw`-2`,String.raw`2`,String.raw`\text{Tidak terdefinisi}`],answer:2,hint:'Periksa dahulu apakah masukan untuk fungsi yang dikerjakan pertama berada pada domainnya.',why:'Negatif dua berada di luar domain fungsi kuadrat yang dibatasi. Rumus kuadrat saja tidak mengizinkan masukan itu. Karena proses pertama tidak terdefinisi, komposisinya juga tidak terdefinisi.',worked:String.raw`-2\notin D_f\quad\Rightarrow\quad g(f(-2))\ \text{tidak terdefinisi}`,review:[['domain-range.html','Domain fungsi'],['fungsi-invers.html','Invers dan pembatasan domain'],['komposisi-fungsi.html','Domain komposisi']]},
{id:'m06',group:'b',kind:'number',tex:String.raw`f(x)=\begin{cases}2x+1,&x<1\\x^2,&x\ge1\end{cases}`,prompt:'Berapa nilai f(f(0))?',n:1,d:1,hint:'Kerjakan fungsi di dalam lebih dahulu. Keluaran pertama menjadi masukan baru; periksa kembali syarat cabangnya.',why:'Masukan nol memakai cabang pertama dan menghasilkan satu. Masukan baru satu memakai cabang kedua karena batasnya termasuk. Kuadrat satu bernilai satu.',worked:String.raw`f(0)=1,\quad f(f(0))=f(1)=1`,review:[['fungsi-per-bagian.html','Memilih cabang fungsi'],['komposisi-fungsi.html','Urutan komposisi']]},
{id:'m07',group:'c',kind:'number',tex:String.raw`h(t)=-t^2+4t,\quad 0\le t\le4`,prompt:'Model tinggi h dinyatakan dalam meter dan waktu t dalam detik. Berapa nilai tinggi maksimum pada domain ini? Tulis angkanya saja.',n:4,d:1,hint:'Ubah ke bentuk puncak atau temukan titik simetrinya. Bedakan tinggi maksimum dari waktu saat dicapai.',why:'Bentuknya negatif kuadrat waktu dikurangi dua, lalu ditambah empat. Nilai terbesar empat tercapai pada waktu dua detik, yang termasuk domain.',worked:String.raw`h(t)=-(t-2)^2+4\le4,\quad h(2)=4`,review:[['fungsi-kuadrat.html','Puncak fungsi kuadrat'],['membaca-grafik.html','Nilai maksimum dan tempat mencapainya']]},
{id:'m08',group:'c',kind:'number',tex:String.raw`P(t)=80\left(\frac12\right)^t,\quad t\ge0`,prompt:'Pada model ini, kapan P(t) menjadi 20? Tulis nilai t.',n:2,d:1,hint:'Bagi kedua ruas dengan delapan puluh. Nyatakan seperempat sebagai pangkat dari setengah.',why:'Dua puluh dibagi delapan puluh adalah seperempat. Faktor setengah dipakai dua kali untuk menghasilkan seperempat, sehingga waktunya dua satuan.',worked:String.raw`\left(\frac12\right)^t=\frac14=\left(\frac12\right)^2\Rightarrow t=2`,review:[['fungsi-eksponensial.html','Faktor peluruhan'],['persamaan-eksponen-log.html','Persamaan eksponensial']]},
{id:'m09',group:'c',kind:'number',tex:String.raw`\sin\theta=\frac35,\quad\theta\ \text{di kuadran II}`,prompt:'Berapa nilai cosinus sudut itu? Tulis pecahan bertanda yang tepat.',n:-4,d:5,hint:'Gunakan jumlah kuadrat sinus dan cosinus sama dengan satu. Kuadran menentukan pilihan tandanya.',why:'Kuadrat cosinus adalah satu dikurangi sembilan per dua puluh lima, yaitu enam belas per dua puluh lima. Di kuadran dua, koordinat mendatar negatif sehingga cosinusnya negatif empat per lima.',worked:String.raw`\cos^2\theta=\frac{16}{25},\quad\cos\theta=-\frac45`,review:[['lingkaran-satuan.html','Tanda sinus dan cosinus'],['identitas-trigonometri.html','Identitas kuadrat']]},
{id:'m10',group:'d',kind:'number',tex:String.raw`f(x)=\begin{cases}\frac{x^2-4}{x-2},&x\ne2\\k,&x=2\end{cases}`,prompt:'Berapa nilai k agar fungsi kontinu di dua?',n:4,d:1,hint:'Cari limit dari bentuk pecahan dengan faktorisasi. Nilai yang dipasang di titik harus sama dengan limit itu.',why:'Di sekitar dua, pecahan sama dengan masukan ditambah dua. Limitnya empat. Mengisi nilai titik dengan empat membuat nilai fungsi dan limitnya sama.',worked:String.raw`\lim_{x\to2}\frac{x^2-4}{x-2}=4\quad\Rightarrow\quad k=4`,review:[['faktorisasi.html','Menyederhanakan dengan syarat'],['fungsi-per-bagian.html','Nilai khusus di titik'],['kekontinuan.html','Memasang nilai agar kontinu']]},
{id:'m11',group:'d',kind:'choice',tex:String.raw`\begin{gathered}f(x)=x^2,\quad x=1\\\frac{f(1+h)-f(1)}h=2+h,\quad h\ne0\end{gathered}`,prompt:'Manakah persamaan garis singgung di masukan satu?',options:[String.raw`y=2x-1`,String.raw`y=2x+1`,String.raw`y=x-1`],answer:0,hint:'Baca limit kemiringan ketika perubahan mendekati nol. Garis singgung juga harus melalui titik pada kurva.',why:'Kemiringan sekan mendekati dua, sedangkan titik kurva adalah satu dan satu. Gunakan keluaran dikurangi satu sama dengan dua kali masukan dikurangi satu.',worked:String.raw`y-1=2(x-1)\Longleftrightarrow y=2x-1`,review:[['laju-perubahan.html','Kemiringan rata-rata'],['garis.html','Persamaan garis'],['garis-singgung.html','Limit kemiringan dan singgung']]},
{id:'m12',group:'d',kind:'choice',tex:String.raw`f(x)=|x|,\quad\frac{f(1)-f(-1)}{1-(-1)}=0`,prompt:'Apakah laju rata-rata nol ini membuktikan turunan di nol juga nol?',options:[String.raw`\text{Ya}`,String.raw`\text{Tidak}`],answer:1,hint:'Bandingkan limit kemiringan dari kiri dan kanan di nol. Satu sekan tidak menentukan seluruh pendekatan.',why:'Kemiringan dari kiri negatif satu dan dari kanan satu. Keduanya berbeda, sehingga turunan dua sisi di nol tidak ada. Laju rata-rata pada satu interval tidak otomatis menjadi laju sesaat.',worked:String.raw`f'_-(0)=-1\ne1=f'_+(0)`,review:[['nilai-mutlak.html','Makna nilai mutlak'],['gagasan-limit.html','Dua arah pendekatan'],['garis-singgung.html','Sudut tajam dan keberadaan turunan']]}
];
function clean(source){const out={};if(!source||typeof source!=='object'||Array.isArray(source))return out;for(const q of questions)if(typeof source[q.id]==='string'&&source[q.id].trim())out[q.id]=source[q.id].trim().slice(0,80);return out;}
function check(q,raw){const s=typeof raw==='string'?raw.trim():'';if(!s)return 'pending';if(q.kind==='number'){const a=num.parseAnswer(s);return !a?'invalid':num.equalAnswer(a,num.rational(q.n,q.d))?'correct':'incorrect';}if(!/^\d+$/.test(s)||Number(s)>=q.options.length)return 'invalid';return Number(s)===q.answer?'correct':'incorrect';}
function assess(source,selected=groups.map(g=>g.id)){const answers=clean(source),items={},totals={correct:0,incorrect:0,invalid:0,pending:0,unchecked:0},review=[];for(const q of questions){const status=selected.includes(q.group)?check(q,answers[q.id]):'unchecked';items[q.id]=status;totals[status]++;if(status==='incorrect')for(const link of q.review)if(!review.some(r=>r[0]===link[0]))review.push(link);}return {...totals,items,review};}
return {groups,questions,clean,check,assess};
});
